import{_ as e,o as a,c as o,ag as i}from"./chunks/framework.BpFM782D.js";const m=JSON.parse('{"title":"strategic-compact","description":"","frontmatter":{},"headers":[],"relativePath":"skills/strategic-compact.md","filePath":"skills/strategic-compact.md"}'),r={name:"skills/strategic-compact.md"};function s(n,t,c,l,d,h){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="strategic-compact" tabindex="-1">strategic-compact <a class="header-anchor" href="#strategic-compact" aria-label="Permalink to &quot;strategic-compact&quot;">​</a></h1><table tabindex="0"><thead><tr><th>欄位</th><th>值</th></tr></thead><tbody><tr><td>名稱</td><td>strategic-compact</td></tr><tr><td>說明</td><td>在邏輯斷點建議手動 context 壓縮，確保跨任務階段保留 context，而非任意自動壓縮。</td></tr><tr><td>Origin</td><td>ECC</td></tr><tr><td>來源目錄</td><td><code>skills/strategic-compact/</code></td></tr></tbody></table><hr><h1 id="strategic-compact-skill" tabindex="-1">Strategic Compact Skill <a class="header-anchor" href="#strategic-compact-skill" aria-label="Permalink to &quot;Strategic Compact Skill&quot;">​</a></h1><p>Suggests manual <code>/compact</code> at strategic points in your workflow rather than relying on arbitrary auto-compaction.</p><h2 id="when-to-activate" tabindex="-1">When to Activate <a class="header-anchor" href="#when-to-activate" aria-label="Permalink to &quot;When to Activate&quot;">​</a></h2><ul><li>Running long sessions that approach context limits (200K+ tokens)</li><li>Working on multi-phase tasks (research → plan → implement → test)</li><li>Switching between unrelated tasks within the same session</li><li>After completing a major milestone and starting new work</li><li>When responses slow down or become less coherent (context pressure)</li></ul><h2 id="why-strategic-compaction" tabindex="-1">Why Strategic Compaction? <a class="header-anchor" href="#why-strategic-compaction" aria-label="Permalink to &quot;Why Strategic Compaction?&quot;">​</a></h2><p>Auto-compaction triggers at arbitrary points:</p><ul><li>Often mid-task, losing important context</li><li>No awareness of logical task boundaries</li><li>Can interrupt complex multi-step operations</li></ul><p>Strategic compaction at logical boundaries:</p><ul><li><strong>After exploration, before execution</strong> — Compact research context, keep implementation plan</li><li><strong>After completing a milestone</strong> — Fresh start for next phase</li><li><strong>Before major context shifts</strong> — Clear exploration context before different task</li></ul><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>The <code>~/.claude/hooks/strategic-compact.sh</code> hook runs on every PreToolUse event and:</p><ol><li><strong>Reads <code>session_id</code></strong> — From stdin JSON payload, stable across hook invocations</li><li><strong>Tracks tool calls</strong> — Counts invocations per session in <code>/tmp/claude-strategic-compact-{session_id}</code></li><li><strong>Threshold detection</strong> — First suggestion at configurable threshold (default: 50 calls)</li><li><strong>Periodic reminders</strong> — Reminds every 25 calls after threshold</li></ol><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Environment variables:</p><ul><li><code>COMPACT_THRESHOLD</code> — Tool calls before first suggestion (default: 50)</li></ul><h2 id="compaction-decision-guide" tabindex="-1">Compaction Decision Guide <a class="header-anchor" href="#compaction-decision-guide" aria-label="Permalink to &quot;Compaction Decision Guide&quot;">​</a></h2><p>Use this table to decide when to compact:</p><table tabindex="0"><thead><tr><th>Phase Transition</th><th>Compact?</th><th>Why</th></tr></thead><tbody><tr><td>Research → Planning</td><td>Yes</td><td>Research context is bulky; plan is the distilled output</td></tr><tr><td>Planning → Implementation</td><td>Yes</td><td>Plan is in TodoWrite or a file; free up context for code</td></tr><tr><td>Implementation → Testing</td><td>Maybe</td><td>Keep if tests reference recent code; compact if switching focus</td></tr><tr><td>Debugging → Next feature</td><td>Yes</td><td>Debug traces pollute context for unrelated work</td></tr><tr><td>Mid-implementation</td><td>No</td><td>Losing variable names, file paths, and partial state is costly</td></tr><tr><td>After a failed approach</td><td>Yes</td><td>Clear the dead-end reasoning before trying a new approach</td></tr></tbody></table><h2 id="what-survives-compaction" tabindex="-1">What Survives Compaction <a class="header-anchor" href="#what-survives-compaction" aria-label="Permalink to &quot;What Survives Compaction&quot;">​</a></h2><p>Understanding what persists helps you compact with confidence:</p><table tabindex="0"><thead><tr><th>Persists</th><th>Lost</th></tr></thead><tbody><tr><td>CLAUDE.md instructions</td><td>Intermediate reasoning and analysis</td></tr><tr><td>TodoWrite task list</td><td>File contents you previously read</td></tr><tr><td>Memory files (<code>~/.claude/memory/</code>)</td><td>Multi-step conversation context</td></tr><tr><td>Git state (commits, branches)</td><td>Tool call history and counts</td></tr><tr><td>Files on disk</td><td>Nuanced user preferences stated verbally</td></tr></tbody></table><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Compact after planning</strong> — Once plan is finalized in TodoWrite, compact to start fresh</li><li><strong>Compact after debugging</strong> — Clear error-resolution context before continuing</li><li><strong>Don&#39;t compact mid-implementation</strong> — Preserve context for related changes</li><li><strong>Read the suggestion</strong> — The hook tells you <em>when</em>, you decide <em>if</em></li><li><strong>Write before compacting</strong> — Save important context to files or memory before compacting</li><li><strong>Use <code>/compact</code> with a summary</strong> — Add a custom message: <code>/compact Focus on implementing auth middleware next</code></li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="https://x.com/affaanmustafa/status/2014040193557471352" target="_blank" rel="noreferrer">The Longform Guide</a> — Token optimization section</li><li>Memory persistence hooks — For state that survives compaction</li><li><code>continuous-learning</code> skill — Extracts patterns before session ends</li></ul>',28)])])}const g=e(r,[["render",s]]);export{m as __pageData,g as default};
